solutions.naive:
class Solution:
    def removeKdigits(self, num: str, k: int) -> str:
        digits = list(num)
        for _ in range(k):
            i = 0
            while i + 1 < len(digits) and digits[i] <= digits[i + 1]:
                i += 1
            if digits:
                digits.pop(i)
        ans = ''.join(digits).lstrip('0')
        return ans if ans else "0"

solutions.better:
class Solution:
    def removeKdigits(self, num, k):
        keep = len(num) - k
        if keep <= 0:
            return "0"
        start = 0
        out = []
        for pos in range(keep):
            end = len(num) - (keep - pos) + 1
            best = start
            for i in range(start, end):
                if num[i] < num[best]:
                    best = i
                    if num[i] == '0':
                        break
            out.append(num[best])
            start = best + 1
        ans = ''.join(out).lstrip('0')
        return ans if ans else "0"

solutions.optimal:
class Solution:
    def removeKdigits(self, num, k):
        stack = []
        for ch in num:
            while k and stack and stack[-1] > ch:
                stack.pop()
                k -= 1
            stack.append(ch)
        if k:
            stack = stack[:-k]
        ans = ''.join(stack).lstrip('0')
        return ans if ans else "0"

